import{_ as e,o as r,c as o,a2 as s}from"./chunks/framework.DQbZ8cc1.js";const p=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"zh/docs/qa.md","filePath":"zh/docs/qa.md"}'),t={name:"zh/docs/qa.md"};function h(l,a,i,c,b,d){return r(),o("div",null,[...a[0]||(a[0]=[s('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to “常见问题”">​</a></h1><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>本页整理面向论坛、问答空间、知识库和讨论场景评估 BBS-GO 时常见的问题。</p></div><h2 id="bbs-go-是什么" tabindex="-1">BBS-GO 是什么？ <a class="header-anchor" href="#bbs-go-是什么" aria-label="Permalink to “BBS-GO 是什么？”">​</a></h2><p>BBS-GO 是面向论坛、知识库与讨论场景的轻量级社区与问答平台。它开源、可自托管，并基于 Go 和 React 构建。</p><h2 id="可以用-bbs-go-搭建什么" tabindex="-1">可以用 BBS-GO 搭建什么？ <a class="header-anchor" href="#可以用-bbs-go-搭建什么" aria-label="Permalink to “可以用 BBS-GO 搭建什么？”">​</a></h2><p>你可以用它搭建公开论坛、产品社区、开发者支持社区、内部问答中心和知识分享社区。</p><h2 id="bbs-go-只是论坛吗" tabindex="-1">BBS-GO 只是论坛吗？ <a class="header-anchor" href="#bbs-go-只是论坛吗" aria-label="Permalink to “BBS-GO 只是论坛吗？”">​</a></h2><p>不是。论坛式讨论是核心场景之一，但 BBS-GO 也支持文章发布、问答式流程、标签、分类、搜索、通知、声誉激励和后台运营管理。</p><h2 id="它和大型论坛系统有什么区别" tabindex="-1">它和大型论坛系统有什么区别？ <a class="header-anchor" href="#它和大型论坛系统有什么区别" aria-label="Permalink to “它和大型论坛系统有什么区别？”">​</a></h2><p>BBS-GO 更强调实用的自托管部署、更低的运维负担，以及论坛 + 问答 + 知识发布的一体化体验。当你需要结构化讨论，但不想引入过重的企业级社区套件时，它会更合适。</p><h2 id="可以私有化部署吗" tabindex="-1">可以私有化部署吗？ <a class="header-anchor" href="#可以私有化部署吗" aria-label="Permalink to “可以私有化部署吗？”">​</a></h2><p>可以。BBS-GO 面向自托管部署设计，支持 Docker、发行包和源码构建。</p><h2 id="支持-docker-吗" tabindex="-1">支持 Docker 吗？ <a class="header-anchor" href="#支持-docker-吗" aria-label="Permalink to “支持 Docker 吗？”">​</a></h2><p>支持。请参考 <a href="./installation/docker.html">Docker 部署</a> 查看 compose 配置和单容器启动方式。</p><h2 id="生产环境推荐使用什么数据库" tabindex="-1">生产环境推荐使用什么数据库？ <a class="header-anchor" href="#生产环境推荐使用什么数据库" aria-label="Permalink to “生产环境推荐使用什么数据库？”">​</a></h2><p>生产环境推荐使用 MySQL。SQLite 适合本地试用和轻量评估。</p><h2 id="是否支持多语言" tabindex="-1">是否支持多语言？ <a class="header-anchor" href="#是否支持多语言" aria-label="Permalink to “是否支持多语言？”">​</a></h2><p>支持。BBS-GO 目前支持 <code>en-US</code> 和 <code>zh-CN</code>，覆盖 Web 端体验和服务端消息。</p><h2 id="在哪里可以试用" tabindex="-1">在哪里可以试用？ <a class="header-anchor" href="#在哪里可以试用" aria-label="Permalink to “在哪里可以试用？”">​</a></h2><p>可以访问在线演示社区：<a href="https://bbs.bbs-go.com" target="_blank" rel="noreferrer">https://bbs.bbs-go.com</a></p><h2 id="在哪里反馈问题" tabindex="-1">在哪里反馈问题？ <a class="header-anchor" href="#在哪里反馈问题" aria-label="Permalink to “在哪里反馈问题？”">​</a></h2><p>请使用 GitHub Issues：<a href="https://github.com/mlogclub/bbs-go/issues" target="_blank" rel="noreferrer">https://github.com/mlogclub/bbs-go/issues</a></p>',22)])])}const m=e(t,[["render",h]]);export{p as __pageData,m as default};
